CREATE TABLE IF NOT EXISTS ip_archives (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, url VARCHAR(512) NOT NULL, title VARCHAR(255) DEFAULT NULL, style_analysis TEXT DEFAULT NULL, topics TEXT DEFAULT NULL, source_json TEXT DEFAULT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ipa_user (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='口播工坊 IP 大脑档案（对标 aigc-human ip-brain）';
